import { useEffect, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import {
  providerNeedsBscAgent, LLM_PROVIDERS,
  DEFAULT_ANTHROPIC_MODEL, DEFAULT_LOCAL_MODEL, DEFAULT_LOCAL_BASE_URL, DEFAULT_NUM_CTX,
  isLocalModelInstalled, pickInstalledLocalModel,
  type LlmProvider,
} from "@/shared/lib/core/llmConfig";
import { Card } from "@/shared/ui/data/Card";
import { Grid } from "@/shared/ui/layout/Grid";
import { Button } from "@/shared/ui/controls/Button";
import { Field, TextField, SelectField } from "@/shared/ui/controls/Field";
import { Box } from "@/shared/ui/layout/Box";

// The provider list + placeholders live in `@data/console/model-defaults.json` (#2416), consumed
// via `LLM_PROVIDERS` / the `DEFAULT_*` model constants from `@/shared/lib/core/llmConfig` — the
// one source for every model default; nothing model-shaped is authored here.
const keyPlaceholder = (p: LlmProvider): string =>
  LLM_PROVIDERS.find((o) => o.id === p)?.keyPlaceholder ?? "";

export function LlmProviderCard() {
  const { claudeApiKey, setClaudeApiKey } = useAppStore();
  const llmProvider = useAppStore(s => s.llmProvider);
  const setLlmProvider = useAppStore(s => s.setLlmProvider);
  const llmModel = useAppStore(s => s.llmModel);
  const setLlmModel = useAppStore(s => s.setLlmModel);
  const openaiKey = useAppStore(s => s.openaiKey);
  const setOpenaiKey = useAppStore(s => s.setOpenaiKey);
  const geminiKey = useAppStore(s => s.geminiKey);
  const setGeminiKey = useAppStore(s => s.setGeminiKey);
  const localBaseUrl = useAppStore(s => s.localBaseUrl);
  const setLocalBaseUrl = useAppStore(s => s.setLocalBaseUrl);
  const llmNumCtx = useAppStore(s => s.llmNumCtx);
  const setLlmNumCtx = useAppStore(s => s.setLlmNumCtx);
  const fleetHarness = useAppStore(s => s.fleetHarness);
  const setFleetHarness = useAppStore(s => s.setFleetHarness);

  const providerKey = llmProvider === "openai" ? openaiKey : llmProvider === "gemini" ? geminiKey : llmProvider === "anthropic" ? claudeApiKey : "";
  const setProviderKey = (v: string) => {
    if (llmProvider === "openai") setOpenaiKey(v);
    else if (llmProvider === "gemini") setGeminiKey(v);
    else if (llmProvider === "anthropic") setClaudeApiKey(v);
  };

  // Local-model preflight (#1830): probe the Ollama endpoint for its installed models — surfaces a
  // down server / wrong URL HERE (before a session hits it mid-task) and offers the model names as
  // suggestions for the free-text model field below.
  const isLocal = providerNeedsBscAgent(llmProvider);
  const [testing, setTesting] = useState(false);
  const [testMsg, setTestMsg] = useState("");
  const [models, setModels] = useState<string[]>([]);

  const probe = async (): Promise<string[] | null> => {
    setTesting(true);
    setTestMsg("");
    try {
      const found = await invoke<string[]>("ollama_models", { baseUrl: localBaseUrl });
      setModels(found);
      setTestMsg(
        found.length
          ? `✓ reachable — ${found.length} model${found.length === 1 ? "" : "s"} installed`
          : "✓ reachable — no models yet (run `ollama pull <model>`)",
      );
      return found;
    } catch (e) {
      setModels([]);
      setTestMsg(`✗ ${String(e)}`);
      return null;
    } finally {
      setTesting(false);
    }
  };
  const testConnection = () => { void probe(); };

  // #176: switching TO a local provider used to just SET llmModel to the packaged default
  // (`modelOnProviderSwitch`, in `@/shared/lib/core/llmConfig`) with nothing checking it against
  // what THIS machine’s Ollama actually has installed — so "out of the box" could silently land
  // on a model that 404s the moment a session starts. Auto-run the same preflight the "test" button
  // already offers, and if the endpoint IS reachable and the model it landed on ISN’T among what’s
  // installed, correct it to one that is (preferring the packaged default’s own tagged install
  // when present). A model the user typed themselves — anything but the still-untouched packaged
  // default — is left alone, same as the manual preflight always has. When the endpoint is
  // unreachable, `probe` leaves `models` empty and this never fires — the packaged default stays.
  useEffect(() => {
    if (!isLocal) return;
    let alive = true;
    void (async () => {
      const found = await probe();
      if (!alive || !found || found.length === 0) return;
      if (llmModel !== "" && isLocalModelInstalled(llmModel, found)) return;
      if (llmModel !== "" && llmModel !== DEFAULT_LOCAL_MODEL) return;
      const corrected = pickInstalledLocalModel(DEFAULT_LOCAL_MODEL, found);
      if (corrected && corrected !== llmModel) {
        setLlmModel(corrected);
        setTestMsg(`✓ reachable — corrected model to an installed one: ${corrected}`);
      }
    })();
    return () => { alive = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- re-probes on provider/URL change, not on every llmModel edit
  }, [isLocal, localBaseUrl]);

  return (
    <Card title="LLM provider" hint={<>Powers planning &amp; assistant calls (autopilot, grader, cleanup).</>}>
      <Grid cols="1.4fr 1fr" gap={14}>
        <SelectField label="Provider" value={llmProvider} onChange={(v) => setLlmProvider(v as LlmProvider)}>
          {LLM_PROVIDERS.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
        </SelectField>
        <TextField
          label="Model"
          value={llmModel}
          onChange={setLlmModel}
          placeholder={isLocal ? DEFAULT_LOCAL_MODEL : DEFAULT_ANTHROPIC_MODEL}
          list={isLocal ? "ollama-models" : undefined}
        />
        {/* the datalist is display:none, so as a grid sibling it generates no box/track */}
        {isLocal && models.length > 0 && (
          <datalist id="ollama-models">
            {models.map((m) => <option key={m} value={m} />)}
          </datalist>
        )}
        {isLocal && (
          <Box style={{ gridColumn: "1 / -1" }}>
            <TextField
              label="Base URL"
              value={localBaseUrl}
              onChange={setLocalBaseUrl}
              placeholder={DEFAULT_LOCAL_BASE_URL}
              trailing={
                <Button onClick={testConnection} disabled={testing}>
                  {testing ? "testing…" : "test"}
                </Button>
              }
              hint={testMsg || (llmProvider === "ollama" ? "Ollama port / API URL." : "OpenAI-compatible endpoint (e.g. Ollama).")}
            />
          </Box>
        )}
        <Box style={{ gridColumn: "1 / -1" }}>
          {(llmProvider === "local" || llmProvider === "ollama") ? (
            <Field label="API key" hint={<>Local provider — no API key needed; set the <b>Base URL</b> above.</>}>{null}</Field>
          ) : (
            <TextField
              label="API key"
              type="password"
              value={providerKey}
              onChange={setProviderKey}
              placeholder={keyPlaceholder(llmProvider)}
              hint="Written to app-state.json on this machine, in plaintext — treat it like any file on disk. The per-pane agent model lives in Settings → General."
            />
          )}
        </Box>
        <Box style={{ gridColumn: "1 / -1" }}>
          {/* NOT LOCKED, and not overridden. This control used to be DISABLED whenever a local
              provider was selected, while rendering "bsc-agent" as its value — so it displayed a
              value it did not honour and the stored one was unreachable. `effectiveHarness` no
              longer reads the provider at all: the provider says which model a bsc-agent session
              talks to, this says whether a session is one. Choosing a local model and leaving this
              on Claude Code is a coherent, common setup — it is how ONE project runs local while
              everything else stays on Claude Code, designated per pane. */}
          <SelectField
            label="Run the agent fleet on"
            value={fleetHarness}
            onChange={(v) => setFleetHarness(v as "claude" | "bsc-agent")}
            hint={providerNeedsBscAgent(llmProvider) && fleetHarness === "claude"
              ? "Claude Code cannot drive the local provider above, so the fleet does NOT use it. Switch this to bsc-agent to run every session on it, or leave it here and designate individual panes local from the pane menu."
              : "Planner, workers + director launch on this harness; bsc-agent runs on the selected LLM with the same role permissions, MCP, and context."}
          >
            <option value="claude">Claude Code (default)</option>
            <option value="bsc-agent">bsc-agent — the provider/model above</option>
          </SelectField>
        </Box>
        {/* The per-agent context cap — REAL now (it was an uncontrolled `defaultValue="64000"`
            placeholder bound to nothing, so the one control that could have prevented a truncated
            local session did nothing at all). Empty means "use the runtime's packaged ceiling", so
            leaving it alone tracks that default instead of pinning a number here. */}
        <TextField
          label="Per-agent context cap"
          value={llmNumCtx}
          onChange={setLlmNumCtx}
          placeholder={String(DEFAULT_NUM_CTX)}
          hint={
            isLocal
              ? <>Tokens (<code>num_ctx</code>). Blank uses the default; <b>0</b> defers to the server.
                  A prompt that <i>reaches</i> this limit is not trimmed — Ollama keeps only the last
                  half and discards the start, where the project&rsquo;s <code>CLAUDE.md</code> is.</>
              : <>Applies to local sessions only; hosted providers manage their own window.</>
          }
        />
      </Grid>
    </Card>
  );
}

