import { describe, it, expect, vi, beforeEach } from "vitest";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { LlmProviderCard } from "@/features/settings/cards/LlmProviderCard";
import { DEFAULT_LOCAL_MODEL } from "@/shared/lib/core/llmConfig";

// #1830: the local-model preflight — the "test" button probes /api/tags via the ollama_models
// command, surfacing a reachable endpoint + installed models (offered as model-field suggestions),
// or a friendly error, instead of a typo'd model / down server only showing up mid-session.
describe("LlmProviderCard — Ollama preflight (#1830)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({ llmProvider: "ollama", localBaseUrl: "http://localhost:11434/v1", llmModel: "" });
  });

  it("lists installed models + offers them as datalist suggestions", async () => {
    vi.mocked(invoke).mockResolvedValue(["llama3.1:8b", "qwen3-coder:latest"]);
    render(<LlmProviderCard />);
    // #176: mounting now auto-probes too, so the "test" button briefly reads "testing…" — wait for
    // that mount preflight to settle before driving the manual click this test is actually about.
    await waitFor(() => expect(screen.getByRole("button", { name: "test" })).toBeInTheDocument());
    fireEvent.click(screen.getByRole("button", { name: "test" }));

    await waitFor(() => screen.getByText(/2 models installed/));
    expect(invoke).toHaveBeenCalledWith("ollama_models", { baseUrl: "http://localhost:11434/v1" });
    // discovered models become datalist <option>s for the free-text model field
    expect(document.querySelector('datalist#ollama-models option[value="qwen3-coder:latest"]')).toBeInTheDocument();
  });

  it("surfaces an unreachable endpoint as an error, not a crash", async () => {
    vi.mocked(invoke).mockRejectedValue("Request failed: connection refused");
    render(<LlmProviderCard />);
    await waitFor(() => expect(screen.getByRole("button", { name: "test" })).toBeInTheDocument());
    fireEvent.click(screen.getByRole("button", { name: "test" }));

    await waitFor(() => screen.getByText(/Request failed/));
  });

  it("auto-corrects the packaged default to an installed model on mount, without a click (#176)", async () => {
    // Out of the box, llmModel already holds the packaged default (qwen3-coder) — this machine's
    // Ollama has something else installed. The card should reconcile that on its own preflight,
    // not only when the user happens to press "test".
    useAppStore.setState({ llmModel: DEFAULT_LOCAL_MODEL });
    vi.mocked(invoke).mockResolvedValue(["qwen3.5:9b", "qwen3.5:35b-a3b"]);
    render(<LlmProviderCard />);

    await waitFor(() => expect(useAppStore.getState().llmModel).toBe("qwen3.5:9b"));
    expect(invoke).toHaveBeenCalledWith("ollama_models", { baseUrl: "http://localhost:11434/v1" });
  });

  it("leaves a model the user explicitly typed alone even when it isn't installed (#176)", async () => {
    useAppStore.setState({ llmModel: "my-custom-finetune" });
    vi.mocked(invoke).mockResolvedValue(["qwen3.5:9b"]);
    render(<LlmProviderCard />);

    await waitFor(() => screen.getByText(/1 model installed/));
    expect(useAppStore.getState().llmModel).toBe("my-custom-finetune");
  });

  it("does not touch the configured model when the endpoint is unreachable (#176)", async () => {
    useAppStore.setState({ llmModel: DEFAULT_LOCAL_MODEL });
    vi.mocked(invoke).mockRejectedValue("Request failed: connection refused");
    render(<LlmProviderCard />);

    await waitFor(() => screen.getByText(/Request failed/));
    expect(useAppStore.getState().llmModel).toBe(DEFAULT_LOCAL_MODEL);
  });
});
